<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_login();
$gradeId=(int)user()['grade_id'];$gradeNumber=user_grade_number();$uid=(int)user()['id'];
$period=($_GET['period']??'all')==='month'?'month':'all';
$dateClause=$period==='month'?" AND sp.awarded_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') ":'';
// Use the complete grade to find personal ranks beyond the displayed top 100.
$sql="SELECT u.id,u.username,u.profile_image,COALESCE(SUM(sp.points),0) points,
 COUNT(DISTINCT CASE WHEN sp.activity_type='lesson_complete' THEN sp.lesson_id END) completed,
 (SELECT ROUND(AVG(best_score)) FROM (SELECT qa2.user_id,qa2.quiz_id,MAX(qa2.percentage) best_score FROM quiz_attempts qa2 GROUP BY qa2.user_id,qa2.quiz_id) scores WHERE scores.user_id=u.id) quiz_average
 FROM users u LEFT JOIN student_points sp ON sp.user_id=u.id $dateClause
 WHERE u.grade_id=? AND u.status='active' GROUP BY u.id
 ORDER BY points DESC,completed DESC,quiz_average DESC,u.id";
$s=db()->prepare($sql);$s->bind_param('i',$gradeId);$s->execute();$rankedStudents=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$leaders=array_slice($rankedStudents,0,100);$myRank=null;$myRow=null;
foreach($rankedStudents as $index=>$student)if((int)$student['id']===$uid){$myRank=$index+1;$myRow=$student;break;}
$myPoints=(int)($myRow['points']??0);$nextGap=$myRank&&$myRank>1?max(0,(int)$rankedStudents[$myRank-2]['points']-$myPoints):null;
$podium=array_slice(array_values(array_filter($leaders,static fn(array $student):bool=>(int)$student['points']>0)),0,3);
$es=db()->prepare("SELECT se.tier,l.title_en,l.title_si,l.title_ta,s.name_en,s.name_si,s.name_ta,se.earned_at FROM student_emblems se JOIN lessons l ON l.id=se.lesson_id JOIN subjects s ON s.id=se.subject_id WHERE se.user_id=? ORDER BY FIELD(se.tier,'master','gold','silver','bronze'),se.earned_at DESC");$es->bind_param('i',$uid);$es->execute();$emblems=$es->get_result()->fetch_all(MYSQLI_ASSOC);$es->close();
$tiers=array_fill_keys(['bronze','silver','gold','master'],0);foreach($emblems as $emblem)if(isset($tiers[$emblem['tier']]))$tiers[$emblem['tier']]++;
function leaderboard_avatar(array $student):string{
 $content=!empty($student['profile_image'])?'<img src="'.e(url('uploads/profiles/'.rawurlencode((string)$student['profile_image']))).'" alt="" loading="lazy">':e(mb_strtoupper(mb_substr((string)$student['username'],0,1)));
 return '<span class="lb-avatar" aria-hidden="true">'.$content.'</span>';
}
$pageTitle='Grade '.$gradeNumber.' Leaderboard';include __DIR__.'/header.php';
?>
