   <?php if(!$podium):?><div class="lb-empty"><?=game_icon('trophy')?><h3>A new chapter starts here.</h3><p>No points earned <?=$period==='month'?'this month':'yet'?>. Complete a lesson to put your learning on the map.</p><a class="btn good" href="<?=url('student/subjects.php')?>">Find a lesson <?=game_icon('arrow')?></a></div><?php else:?><div class="lb-podium"><?php foreach([1,0,2] as $position):if(!isset($podium[$position]))continue;$student=$podium[$position];$place=$position+1;$isMe=(int)$student['id']===$uid;?><article class="lb-podium-place lb-place-<?=$place?> <?=$isMe?'lb-is-me':''?>"><div class="lb-podium-avatar"><?php if($place===1):?><span class="lb-crown"><?=game_icon('crown')?></span><?php endif;?><?=leaderboard_avatar($student)?><b><?=$place?></b></div><h3 title="@<?=e($student['username'])?>">@<?=e($student['username'])?></h3><span class="lb-podium-caption"><?=$isMe?'That’s you!':($place===1?'Leading the way':'Knowledge explorer')?></span><div class="lb-podium-step"><strong><?=number_format((int)$student['points'])?><small>XP</small></strong><span><?=$place===1?'GOLD':($place===2?'SILVER':'BRONZE')?> POSITION</span></div></article><?php endforeach;?></div><?php endif;?>
  </section>
  <section class="lb-panel lb-rankings" id="rankings"><div class="lb-section-head"><div><span class="lb-eyebrow">YOUR GRADE. YOUR COMMUNITY.</span><h2>The explorer standings</h2></div><span class="lb-list-count">Top <?=count($leaders)?></span></div><label class="lb-search"><?=game_icon('search')?><input type="search" id="lbSearch" placeholder="Find a username in the top 100" aria-label="Search the displayed rankings" autocomplete="off"></label><p class="lb-search-status" id="lbSearchStatus" role="status" aria-live="polite"></p><div class="lb-table-head" aria-hidden="true"><span>RANK</span><span>EXPLORER</span><span>LESSONS</span><span>XP</span></div>
   <ol class="lb-rank-list" aria-label="Grade <?=$gradeNumber?> rankings"><?php foreach($leaders as $index=>$student):$rank=$index+1;$isMe=(int)$student['id']===$uid;?><li class="lb-rank-row <?=$isMe?'lb-your-row':''?>" data-username="<?=e(mb_strtolower((string)$student['username']))?>" <?=$isMe?'id="my-ranking"':''?> value="<?=$rank?>"><span class="lb-rank-number <?=$rank<=3?'lb-rank-medal lb-medal-'.$rank:''?>" aria-label="Rank <?=$rank?>"><?=$rank<=3?game_icon($rank===1?'crown':'star'):''?><b><?=$rank?></b></span><div class="lb-student"><?=leaderboard_avatar($student)?><div><strong>@<?=e($student['username'])?> <?=$isMe?'<span class="lb-you-tag">YOU</span>':''?></strong><small><?=$student['quiz_average']===null?'Your next discovery awaits':(int)$student['quiz_average'].'% best-quiz average'?></small></div></div><span class="lb-lessons"><?=(int)$student['completed']?><small>lessons</small></span><span class="lb-row-xp"><?=number_format((int)$student['points'])?><small>XP</small></span></li><?php endforeach;?></ol>
   <div class="lb-no-results" hidden><?=game_icon('search')?><h3>No explorer found</h3><p>Try another username. Search covers the displayed top 100.</p></div><?php if(!$leaders):?><p class="lb-empty">Your grade’s rankings will appear here.</p><?php endif;?><p class="lb-ranking-note"><?=game_icon('shield')?> Ranked by XP, then completed lessons, then best-quiz average. Final ties use account order. Quiz averages cover all time.</p>
  </section>
 </div><aside class="lb-sidebar" aria-label="Your achievements">
  <section class="lb-panel lb-my-card"><span class="lb-eyebrow">YOUR PLACE IN THE ADVENTURE</span><div class="lb-my-rank"><?=game_icon('target')?><strong><?=$myRank?'#'.number_format($myRank):'—'?></strong><span>of <?=number_format(count($rankedStudents))?> explorers</span></div><h2>Keep your story going.</h2><p><?=$myRank===1?'You’re leading your grade. Keep exploring and inspiring.':($nextGap===0?'You’re level on XP with the next explorer. Lesson completions and quiz scores break ties.':($nextGap!==null?number_format($nextGap).' XP to match the next explorer. Every lesson is a step forward.':'Your next discovery is a great place to start.'))?></p><div class="lb-my-stats"><div><strong><?=number_format($myPoints)?></strong><span><?=$period==='month'?'Monthly XP':'Total XP'?></span></div><div><strong><?=(int)($myRow['completed']??0)?></strong><span>Lessons<?=$period==='month'?' this month':''?></span></div></div><a class="btn good" href="<?=url('student/subjects.php')?>">Continue learning <?=game_icon('arrow')?></a><?php if($myRank&&$myRank<=100):?><a class="lb-find-me" href="#my-ranking">Find me in the standings ↓</a><?php else:?><small class="lb-outside">Your position includes everyone in your grade, beyond the displayed top 100.</small><?php endif;?></section>
  <section class="lb-panel lb-trophy-shelf"><div class="lb-section-head"><div><span class="lb-eyebrow">YOUR HARD-EARNED HIGHLIGHTS</span><h2>My trophy cabinet</h2></div></div><div class="lb-tiers"><?php foreach($tiers as $tier=>$count):?><div class="lb-tier lb-tier-<?=e($tier)?> <?=$count?'is-earned':''?>"><span><?=game_icon($tier==='master'?'crown':($tier==='bronze'?'shield':'star'))?></span><strong><?=ucfirst($tier)?></strong><small><?=$count?> earned</small></div><?php endforeach;?></div><p class="lb-cabinet-note">Lifetime lesson emblems · <?=count($emblems)?> earned</p><?php if($emblems):?><details class="lb-emblem-details"><summary>Explore my lesson emblems</summary><div class="lb-emblem-list"><?php foreach($emblems as $emblem):?><div><span class="lb-emblem-tier"><?=e(ucfirst($emblem['tier']))?></span><strong><?=e(locale_value($emblem,'title'))?></strong><small><?=e(locale_value($emblem,'name'))?></small></div><?php endforeach;?></div></details><?php else:?><p class="lb-cabinet-note">Complete a lesson to earn your first Bronze emblem.</p><?php endif;?></section>
